function Toggle({checked,onChange,label}:any){return <button type="button" className="toggle-line" role="switch" aria-checked={!!checked} onClick={()=>onChange(!checked)}><span>{label}</span><span className={'toggle '+(checked?'on':'')}><i/></span></button>;}
function CanvasPreview({task,variant,assets,safe=false,onErrors,onSelectLayer,onDrag}:any){const ref=useRef<HTMLCanvasElement>(null);const dragging=useRef<{x:number;y:number}|null>(null);useEffect(()=>{let active=true;if(ref.current&&variant)drawVariant(ref.current,task,variant,{scale:Math.min(1,1200/task[variant.device as Device][0]),safe,assets}).then(r=>active&&onErrors?.(r.errors)).catch(e=>active&&onErrors?.([e.message]));return()=>{active=false;};},[task,variant,safe,assets.map((a:any)=>a.id+a.data.url).join('|')]);return <canvas ref={ref} className={'preview-canvas '+(onDrag?'can-drag':'')} role="img" aria-label={variant?.device==='desktop'?'电脑端图片预览':'手机端图片预览'} onPointerDown={onDrag?(e)=>{e.currentTarget.setPointerCapture(e.pointerId);dragging.current={x:e.clientX,y:e.clientY};}:undefined} onPointerUp={onDrag?(e)=>{if(dragging.current){const r=e.currentTarget.getBoundingClientRect();const dx=(e.clientX-dragging.current.x)/r.width,dy=(e.clientY-dragging.current.y)/r.height;if(Math.abs(dx)+Math.abs(dy)>.003)onDrag(dx,dy);else onSelectLayer?.();}dragging.current=null;}:undefined}/>;}

