   const res=await ai('image',{project:projectId,task:t,taskId,approvedVariantId:base?.id,stage,assets:sourceAssets,variantUrl:base?.url,prompt:target.instruction,regions:target.sourceRegions||target.regions,mask:target.mask,device:target.device,width:w,height:h});upsert(res.result.asset);
   const v:Variant={...baseVariant(t,target.device,target.group),...(base||{}),id:uid(),parentId:base?.id,url:res.result.url,source:'api',label:stage==='high'?'高质量增强':base?'AI 调整':'AI 生成',layers:base?.layers||layoutLayers(t,target.device),approved:false,revision:nextRevision(t,target.device,target.group),created:new Date().toISOString(),regions:[],editRequest:base?{instruction:target.instruction,regions:target.regions}:undefined};
